UPDATE ai_model
SET model_key = #{modelKey}, model_name = #{modelName}, provider = #{provider},
    api_key = #{apiKey}, base_url = #{baseUrl}, enabled = #{enabled}, sort_order = #{sortOrder},
    update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}
WHERE id = #{id}

UPDATE ai_model
SET test_status = #{testStatus}, test_message = #{testMessage}, test_time = NOW(), update_time = NOW()
WHERE id = #{id}
